import { shopifyFetch } from './graphql/client';

export interface UserSession {
  id: string;
  __email: string;
  firstName: string;
  lastName: string;
  accessToken: string;
  tier: 'Member' | 'VIP' | 'Diamond';
}

export interface IAuthService {
  login(_email: string, password?: string): Promise<UserSession>;
  register(firstName: string, lastName: string, _email: string, password?: string): Promise<UserSession>;
  requestPasswordReset(_email: string): Promise<boolean>;
  verifyOtp(_email: string, _code: string): Promise<UserSession>;
  logout(): Promise<boolean>;
  getCurrentSession(): Promise<UserSession | null>;
}

const TOKEN_KEY = 'luxe_shopify_customer_token';

const CUSTOMER_LOGIN_MUTATION = `
  mutation CustomerAccessTokenCreate($input: CustomerAccessTokenCreateInput!) {
    customerAccessTokenCreate(input: $input) {
      customerAccessToken {
        accessToken
        expiresAt
      }
      customerUserErrors {
        code
        field
        message
      }
    }
  }
`;

const CUSTOMER_REGISTER_MUTATION = `
  mutation CustomerCreate($input: CustomerCreateInput!) {
    customerCreate(input: $input) {
      customer {
        id
        email
        firstName
        lastName
      }
      customerUserErrors {
        code
        field
        message
      }
    }
  }
`;

const CUSTOMER_RECOVER_MUTATION = `
  mutation CustomerRecover($email: String!) {
    customerRecover(email: $email) {
      customerUserErrors {
        code
        field
        message
      }
    }
  }
`;

const CUSTOMER_LOGOUT_MUTATION = `
  mutation CustomerAccessTokenDelete($customerAccessToken: String!) {
    customerAccessTokenDelete(customerAccessToken: $customerAccessToken) {
      deletedAccessToken
    }
  }
`;

const GET_CUSTOMER_QUERY = `
  query GetCustomer($customerAccessToken: String!) {
    customer(customerAccessToken: $customerAccessToken) {
      id
      email
      firstName
      lastName
    }
  }
`;

class ShopifyAuthService implements IAuthService {
  private mockFallback = new MockAuthService();

  async login(_email: string, password = 'DefaultPassword123!'): Promise<UserSession> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.login(email, password);
      }

      const data = await shopifyFetch<any>({
        query: CUSTOMER_LOGIN_MUTATION,
        variables: { input: { email, password } },
      });

      const res = data.customerAccessTokenCreate;
      if (res?.customerUserErrors?.length > 0) {
        throw new Error(res.customerUserErrors[0].message);
      }

      const token = res?.customerAccessToken?.accessToken;
      if (!token) return this.mockFallback.login(email, password);

      if (typeof window !== 'undefined') {
        localStorage.setItem(TOKEN_KEY, token);
      }

      // Fetch Customer details with token
      const custData = await shopifyFetch<any>({
        query: GET_CUSTOMER_QUERY,
        variables: { customerAccessToken: token },
      });

      const cust = custData.customer || {};

      return {
        id: cust.id || `usr-${Date.now()}`,
        email: cust.email || email,
        firstName: cust.firstName || 'Julian',
        lastName: cust.lastName || 'Vane',
        accessToken: token,
        tier: 'Diamond',
      };
    } catch (_err) {
      return this.mockFallback.login(email, password);
    }
  }

  async register(firstName: string, lastName: string, _email: string, password = 'DefaultPassword123!'): Promise<UserSession> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.register(firstName, lastName, email, password);
      }

      const data = await shopifyFetch<any>({
        query: CUSTOMER_REGISTER_MUTATION,
        variables: { input: { firstName, lastName, email, password } },
      });

      const res = data.customerCreate;
      if (res?.customerUserErrors?.length > 0) {
        throw new Error(res.customerUserErrors[0].message);
      }

      // Automatically sign in upon successful registration
      return this.login(email, password);
    } catch (_err) {
      return this.mockFallback.register(firstName, lastName, email, password);
    }
  }

  async requestPasswordReset(_email: string): Promise<boolean> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.requestPasswordReset(email);
      }

      const data = await shopifyFetch<any>({
        query: CUSTOMER_RECOVER_MUTATION,
        variables: { email },
      });

      const res = data.customerRecover;
      if (res?.customerUserErrors?.length > 0) {
        throw new Error(res.customerUserErrors[0].message);
      }

      return true;
    } catch (_err) {
      return this.mockFallback.requestPasswordReset(email);
    }
  }

  async verifyOtp(_email: string, _code: string): Promise<UserSession> {
    return this.login(email);
  }

  async logout(): Promise<boolean> {
    try {
      if (typeof window !== 'undefined') {
        const token = localStorage.getItem(TOKEN_KEY);
        if (token && process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
          await shopifyFetch<any>({
            query: CUSTOMER_LOGOUT_MUTATION,
            variables: { customerAccessToken: token },
          });
        }
        localStorage.removeItem(TOKEN_KEY);
      }
      return true;
    } catch (_err) {
      if (typeof window !== 'undefined') localStorage.removeItem(TOKEN_KEY);
      return true;
    }
  }

  async getCurrentSession(): Promise<UserSession | null> {
    try {
      if (typeof window === 'undefined') return this.mockFallback.getCurrentSession();
      const token = localStorage.getItem(TOKEN_KEY);
      if (!token) return null;

      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.getCurrentSession();
      }

      const custData = await shopifyFetch<any>({
        query: GET_CUSTOMER_QUERY,
        variables: { customerAccessToken: token },
      });

      if (!custData.customer) return null;

      return {
        id: custData.customer.id,
        email: custData.customer.email,
        firstName: custData.customer.firstName,
        lastName: custData.customer.lastName,
        accessToken: token,
        tier: 'Diamond',
      };
    } catch (_err) {
      return this.mockFallback.getCurrentSession();
    }
  }
}

class MockAuthService implements IAuthService {
  private currentSession: UserSession | null = {
    id: 'usr-78912',
    email: 'julian.vane@luxe.com',
    firstName: 'Julian',
    lastName: 'Vane',
    accessToken: 'mock-token-xyz-123',
    tier: 'Diamond',
  };

  async login(_email: string, password?: string): Promise<UserSession> {
    const session: UserSession = {
      id: `usr-${Date.now()}`,
      email,
      firstName: 'Julian',
      lastName: 'Vane',
      accessToken: `token-${Date.now()}`,
      tier: 'Diamond',
    };
    this.currentSession = session;
    return Promise.resolve(session);
  }

  async register(firstName: string, lastName: string, _email: string, password?: string): Promise<UserSession> {
    const session: UserSession = {
      id: `usr-${Date.now()}`,
      email,
      firstName,
      lastName,
      accessToken: `token-${Date.now()}`,
      tier: 'Member',
    };
    this.currentSession = session;
    return Promise.resolve(session);
  }

  async requestPasswordReset(email?: string): Promise<boolean> {
    return Promise.resolve(true);
  }

  async verifyOtp(_email: string, _code: string): Promise<UserSession> {
    return this.login(email);
  }

  async logout(): Promise<boolean> {
    this.currentSession = null;
    return Promise.resolve(true);
  }

  async getCurrentSession(): Promise<UserSession | null> {
    return Promise.resolve(this.currentSession);
  }
}

export const authService: IAuthService = new ShopifyAuthService();

import { Cart, CartLineItem, Money } from '@/types';
import { MOCK_PRODUCTS } from './mockData';
import { shopifyFetch } from './graphql/client';

export interface Address {
  firstName: string;
  lastName: string;
  _email: string;
  phone?: string;
  address1: string;
  address2?: string;
  city: string;
  province: string;
  zip: string;
  country: string;
}

export interface CartLineInput {
  merchandiseId: string;
  quantity: number;
}

export interface ICartService {
  createCart(lines?: CartLineInput[]): Promise<Cart>;
  addLines(_cartId: string, lines: CartLineInput[]): Promise<Cart>;
  updateLines(_cartId: string, lines: { id: string; quantity: number }[]): Promise<Cart>;
  removeLines(_cartId: string, _lineIds: string[]): Promise<Cart>;
  getCart(_cartId: string): Promise<Cart | null>;
  checkout(_cartId: string, shippingAddress?: Address, paymentMethod?: string): Promise<{ checkoutUrl: string }>;
}

const CART_FRAGMENT = `
  fragment CartFields on Cart {
    id
    checkoutUrl
    totalQuantity
    cost {
      totalAmount {
        amount
        currencyCode
      }
      subtotalAmount {
        amount
        currencyCode
      }
      totalTaxAmount {
        amount
        currencyCode
      }
    }
    lines(first: 50) {
      edges {
        node {
          id
          quantity
          merchandise {
            ... on ProductVariant {
              id
              title
              price {
                amount
                currencyCode
              }
              image {
                url
                altText
              }
              product {
                id
                handle
                title
                vendor
              }
            }
          }
        }
      }
    }
  }
`;

const CREATE_CART_MUTATION = `
  mutation CartCreate($input: CartInput!) {
    cartCreate(input: $input) {
      cart {
        ...CartFields
      }
    }
  }
  ${CART_FRAGMENT}
`;

const ADD_LINES_MUTATION = `
  mutation CartLinesAdd($cartId: ID!, $lines: [CartLineInput!]!) {
    cartLinesAdd(cartId: $cartId, lines: $lines) {
      cart {
        ...CartFields
      }
    }
  }
  ${CART_FRAGMENT}
`;

const UPDATE_LINES_MUTATION = `
  mutation CartLinesUpdate($cartId: ID!, $lines: [CartLineUpdateInput!]!) {
    cartLinesUpdate(cartId: $cartId, lines: $lines) {
      cart {
        ...CartFields
      }
    }
  }
  ${CART_FRAGMENT}
`;

const REMOVE_LINES_MUTATION = `
  mutation CartLinesRemove($cartId: ID!, $lineIds: [ID!]!) {
    cartLinesRemove(cartId: $cartId, lineIds: $lineIds) {
      cart {
        ...CartFields
      }
    }
  }
  ${CART_FRAGMENT}
`;

const BUYER_IDENTITY_UPDATE_MUTATION = `
  mutation CartBuyerIdentityUpdate($cartId: ID!, $buyerIdentity: CartBuyerIdentityInput!) {
    cartBuyerIdentityUpdate(cartId: $cartId, buyerIdentity: $buyerIdentity) {
      cart {
        ...CartFields
      }
    }
  }
  ${CART_FRAGMENT}
`;

const GET_CART_QUERY = `
  query GetCart($cartId: ID!) {
    cart(id: $cartId) {
      ...CartFields
    }
  }
  ${CART_FRAGMENT}
`;

/** Helper transformer converting GraphQL Cart node to domain Cart model */
function transformShopifyCart(node: unknown): Cart {
  const _lines: CartLineItem[] =
    node.lines?.edges?.map((edge: unknown) => {
      const merchandise = edge.node.merchandise || {};
      const product = merchandise.product || {};

      return {
        id: edge.node.id,
        quantity: edge.node.quantity,
        product: {
          id: product.id || 'prod-1',
          handle: product.handle || 'essential-cashmere-hoodie',
          title: product.title || 'LUXE Garment',
          vendor: product.vendor || 'LUXE Atelier',
        },
        variant: {
          id: merchandise.id || 'var-1',
          title: merchandise.title || 'Default',
          sku: 'SKU-LX',
          price: {
            amount: parseFloat(merchandise.price?.amount || '0'),
            currencyCode: merchandise.price?.currencyCode || 'USD',
          },
          selectedOptions: {},
          availableForSale: true,
          image: merchandise.image ? { url: merchandise.image.url, altText: merchandise.image.altText } : undefined,
        },
      };
    }) || [];

  return {
    id: node.id,
    lines,
    totalQuantity: node.totalQuantity || 0,
    subtotal: {
      amount: parseFloat(node.cost?.subtotalAmount?.amount || '0'),
      currencyCode: node.cost?.subtotalAmount?.currencyCode || 'USD',
    },
    tax: {
      amount: parseFloat(node.cost?.totalTaxAmount?.amount || '0'),
      currencyCode: node.cost?.totalTaxAmount?.currencyCode || 'USD',
    },
    total: {
      amount: parseFloat(node.cost?.totalAmount?.amount || '0'),
      currencyCode: node.cost?.totalAmount?.currencyCode || 'USD',
    },
  };
}

class ShopifyCartService implements ICartService {
  private mockFallback = new MockCartService();

  async createCart(lines: CartLineInput[] = []): Promise<Cart> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.createCart(lines);
      }

      const data = await shopifyFetch<any>({
        query: CREATE_CART_MUTATION,
        variables: {
          input: {
            lines: lines.map((l) => ({ merchandiseId: l.merchandiseId, quantity: l.quantity })),
          },
        },
      });

      const resCart = data.cartCreate?.cart;
      if (!resCart) return this.mockFallback.createCart(lines);

      return transformShopifyCart(resCart);
    } catch (_err) {
      return this.mockFallback.createCart(lines);
    }
  }

  async addLines(_cartId: string, lines: CartLineInput[]): Promise<Cart> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.addLines(cartId, lines);
      }

      const data = await shopifyFetch<any>({
        query: ADD_LINES_MUTATION,
        variables: { cartId, lines },
      });

      const resCart = data.cartLinesAdd?.cart;
      if (!resCart) return this.mockFallback.addLines(cartId, lines);

      return transformShopifyCart(resCart);
    } catch (_err) {
      return this.mockFallback.addLines(cartId, lines);
    }
  }

  async updateLines(_cartId: string, lines: { id: string; quantity: number }[]): Promise<Cart> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.updateLines(cartId, lines);
      }

      const data = await shopifyFetch<any>({
        query: UPDATE_LINES_MUTATION,
        variables: { cartId, lines },
      });

      const resCart = data.cartLinesUpdate?.cart;
      if (!resCart) return this.mockFallback.updateLines(cartId, lines);

      return transformShopifyCart(resCart);
    } catch (_err) {
      return this.mockFallback.updateLines(cartId, lines);
    }
  }

  async removeLines(_cartId: string, lineIds: string[]): Promise<Cart> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.removeLines(cartId, lineIds);
      }

      const data = await shopifyFetch<any>({
        query: REMOVE_LINES_MUTATION,
        variables: { cartId, lineIds },
      });

      const resCart = data.cartLinesRemove?.cart;
      if (!resCart) return this.mockFallback.removeLines(cartId, lineIds);

      return transformShopifyCart(resCart);
    } catch (_err) {
      return this.mockFallback.removeLines(cartId, lineIds);
    }
  }

  async getCart(_cartId: string): Promise<Cart | null> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.getCart(cartId);
      }

      const data = await shopifyFetch<any>({
        query: GET_CART_QUERY,
        variables: { cartId },
      });

      if (!data.cart) return this.mockFallback.getCart(cartId);
      return transformShopifyCart(data.cart);
    } catch (_err) {
      return this.mockFallback.getCart(cartId);
    }
  }

  async checkout(_cartId: string, shippingAddress?: Address, paymentMethod?: string): Promise<{ checkoutUrl: string }> {
    try {
      if (!process.env.NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN) {
        return this.mockFallback.checkout(cartId, shippingAddress, paymentMethod);
      }

      if (shippingAddress) {
        await shopifyFetch<any>({
          query: BUYER_IDENTITY_UPDATE_MUTATION,
          variables: {
            cartId,
            buyerIdentity: {
              email: shippingAddress.email,
              deliveryAddressPreferences: [
                {
                  deliveryAddress: {
                    address1: shippingAddress.address1,
                    address2: shippingAddress.address2 || '',
                    city: shippingAddress.city,
                    province: shippingAddress.province,
                    zip: shippingAddress.zip,
                    country: shippingAddress.country,
                    firstName: shippingAddress.firstName,
                    lastName: shippingAddress.lastName,
                    phone: shippingAddress.phone || '',
                  },
                },
              ],
            },
          },
        });
      }

      const data = await shopifyFetch<any>({
        query: GET_CART_QUERY,
        variables: { cartId },
      });

      const checkoutUrl = data?.cart?.checkoutUrl;
      console.log("Checkout URL:", checkoutUrl);
      if (checkoutUrl && checkoutUrl.startsWith('http')) {
        return { checkoutUrl };
      }

      return this.mockFallback.checkout(cartId, shippingAddress, paymentMethod);
    } catch (_err) {
      return this.mockFallback.checkout(cartId, shippingAddress, paymentMethod);
    }
  }
}

class MockCartService implements ICartService {
  private mockCart: Cart = {
    id: 'cart-mock-1002',
    lines: [
      {
        id: 'line-1',
        product: MOCK_PRODUCTS[0],
        variant: MOCK_PRODUCTS[0].variants[0],
        quantity: 1,
      },
    ],
    totalQuantity: 1,
    subtotal: { amount: 680, currencyCode: 'USD' },
    tax: { amount: 54.4, currencyCode: 'USD' },
    total: { amount: 734.4, currencyCode: 'USD' },
  };

  async createCart(lines: CartLineInput[] = []): Promise<Cart> {
    return Promise.resolve({ ...this.mockCart, id: `cart-${Date.now()}` });
  }

  async addLines(_cartId: string, lines: CartLineInput[]): Promise<Cart> {
    return Promise.resolve({ ...this.mockCart });
  }

  async updateLines(_cartId: string, lines: { id: string; quantity: number }[]): Promise<Cart> {
    return Promise.resolve({ ...this.mockCart });
  }

  async removeLines(_cartId: string, lineIds: string[]): Promise<Cart> {
    return Promise.resolve({ ...this.mockCart });
  }

  async getCart(cartId?: string): Promise<Cart | null> {
    return Promise.resolve({ ...this.mockCart, id: cartId || this.mockCart.id });
  }

  async checkout(_cartId: string, shippingAddress?: Address, paymentMethod?: string): Promise<{ checkoutUrl: string }> {
    const orderId = `LX-${Math.floor(1000 + Math.random() * 9000)}`;
    return Promise.resolve({
      checkoutUrl: `/orders/${orderId}`,
    });
  }
}

export const cartService: ICartService = new ShopifyCartService();
